import json,subprocess
payload=r'''
import os,stat,json,re,subprocess
from pathlib import Path
out={"usage_mib":{},"secrets":{},"vault":{},"units":{},"services":{},"folders":[],"python":{}}
for path in ["/srv/projects/pink-iptv","/srv/projects/pink-iptv/tests/device-proof","/srv/projects/pink-iptv/android","/srv/projects/pink-iptv/backend","/srv/projects/pink-iptv/vpn","/srv/projects/pink-iptv/private","/srv/projects/pink-iptv/.git","/srv/projects/jellyfin-server","/root/project-secrets"]:
 if Path(path).exists():
  try:
   p=subprocess.run(["du","-sm","--",path],capture_output=True,text=True,timeout=50)
   out["usage_mib"][path]=int(p.stdout.split()[0]) if p.returncode==0 else "unreadable"
  except Exception as e:out["usage_mib"][path]=type(e).__name__
for name in ["backend.env","secrets.env","vpn.env"]:
 p=Path("/srv/projects/pink-iptv/private/systemd-env")/name
 obj={"exists":p.is_file()}
 if p.is_file():
  st=p.stat();obj["mode"]=oct(stat.S_IMODE(st.st_mode));obj["size_bytes"]=st.st_size
  keys=[]
  for line in p.read_text(errors="replace").splitlines():
   m=re.match(r"^(?:export\\s+)?([A-Za-z_][A-Za-z0-9_]*)\\s*=",line)
   if m:keys.append(m.group(1))
  obj["key_names"]=keys[:100]
 out["secrets"][name]=obj
p=Path("/root/project-secrets")
out["vault"]["present"]=p.is_dir()
if p.is_dir():
 out["vault"]["mode"]=oct(stat.S_IMODE(p.stat().st_mode))
 out["vault"]["entries"]=[{"name":x.name,"type":"dir" if x.is_dir() else "file","mode":oct(stat.S_IMODE(x.stat().st_mode))} for x in sorted(p.iterdir(),key=lambda p:p.name) if not x.is_symlink()][:45]
for name in ["pink-iptv-backend.service","pink-vpn.service","project-secrets-backup.timer","postgresql.service"]:
 p=subprocess.run(["systemctl","is-active",name],capture_output=True,text=True,timeout=6)
 out["services"][name]=p.stdout.strip() if p.returncode==0 else "inactive_or_unknown"
for name in ["pink-iptv-backend.service","pink-vpn.service"]:
 p=subprocess.run(["systemctl","cat",name],capture_output=True,text=True,timeout=7)
 rows=[]
 for line in p.stdout.splitlines():
  s=line.strip()
  if s.startswith("EnvironmentFile="):rows.append(s[:160])
  if s.startswith("ExecStart="):
   cmd=s.partition("=")[2].split(" ")[0]
   rows.append("ExecStart_binary="+cmd[:150])
 out["units"][name]=rows[:20]
root=Path("/srv/projects/pink-iptv")
if root.is_dir():
 out["folders"]=[{"name":x.name,"type":"dir" if x.is_dir() else "file"} for x in sorted(root.iterdir(),key=lambda p:p.name) if not x.is_symlink()][:60]
for cmd in (["python3","--version"],["psql","--version"],["git","--version"]):
 try:
  p=subprocess.run(cmd,capture_output=True,text=True,timeout=5)
  out["python"][cmd[0]]=p.stdout.strip()[:120] or p.stderr.strip()[:120]
 except Exception as e:out["python"][cmd[0]]=type(e).__name__
print(json.dumps(out,sort_keys=True))
'''
p=subprocess.run(["sudo","-n","python3","-c",payload],capture_output=True,text=True,timeout=150)
if p.returncode:
 print(json.dumps({"sudo_audit_status":"failed","returncode":p.returncode,"error_type":"permission_or_script_error"}));raise SystemExit(0)
try:
 x=json.loads(p.stdout)
 print(json.dumps(x,sort_keys=True))
except Exception:
 print(json.dumps({"sudo_audit_status":"invalid_json","bytes":len(p.stdout)}))
